const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={reviewed:false,mapCategory:'Все категории',radius:'1 км',language:'Русский',speechLanguage:'Русский'};
let saved={};try{saved=JSON.parse(localStorage.getItem('qalapulse.lab4.draft')||'{}');}catch{}
const values={...defaults,...saved};
let current='01',modal=null,tab='prototype',confirmed=false,voice='idle',timer=null,toastTimer=null;
function persist(){const data={...values};delete data.password;delete data.email;delete data.name;try{localStorage.setItem('qalapulse.lab4.draft',JSON.stringify(data));}catch{}}
function value(b){return values[b.key]??b.value??'';}
function block(b,staticMode=false){
 const disabled=b.disabled||(b.gate&&!values[b.gate]);
 if(b.type==='button')return `<button class="btn ${b.secondary?'secondary':''} ${b.loading?'loading':''}" data-action="${esc(b.action)}" ${disabled?'disabled':''}>${esc(b.text)}</button>`;
 if(b.type==='field')return `<label class="field"><span>${esc(b.text)}</span>${b.multiline?`<textarea data-key="${esc(b.key)}" rows="3">${esc(value(b))}</textarea>`:`<input data-key="${esc(b.key)}" type="${esc(b.inputType||'text')}" value="${esc(value(b))}" placeholder="${esc(b.placeholder||'')}" ${b.required?'required':''} ${b.inputType==='number'?'min="1" max="10"':''}>`}</label>`;
 if(b.type==='choice')return `<label class="choice">${esc(b.text)}<select data-key="${esc(b.key)}">${b.choices.map(x=>`<option ${value(b)===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
 if(b.type==='checkbox')return `<label class="check"><input type="checkbox" data-key="${b.key}" ${values[b.key]?'checked':''}><span>${esc(b.text)}</span></label>`;
 if(b.type==='card')return `<button class="card" data-action="${esc(b.action)}" data-searchable="${esc(b.text.toLowerCase())}"><small>${esc(b.status||'Опубликовано в QalaPulse')}</small><strong>${esc(b.text)}</strong><small>${esc(b.meta)}</small></button>`;
 if(b.type==='photo')return `<div class="placeholder" style="height:${b.height||160}px"><svg viewBox="0 0 48 48" aria-hidden="true"><rect x="3" y="3" width="42" height="42"/><path d="M3 3L45 45M45 3L3 45"/></svg><span>${esc(b.text)}</span></div>`;
 if(b.type==='map')return `<button class="placeholder map" style="height:${b.height||180}px" data-action="${esc(b.action)}" aria-label="${esc(b.text)}"><span class="map-title">${esc(b.text)}</span><span class="pin">1</span><span class="pin second">2</span><small>● Условная точка · Алматы</small></button>`;
 if(b.type==='progress')return `<div class="progress"><progress value="${b.value}" max="7"></progress>${esc(b.text)}</div>`;
 if(b.type==='voice')return `<div class="voice"><strong>${esc(b.text)}</strong><div class="controls"><button data-action="voice-record">${voice==='recording'?'Стоп':'Записать'}</button><button data-action="voice-play" ${voice==='idle'||voice==='recording'?'disabled':''}>${voice==='playing'?'Остановить':'Прослушать'}</button><button data-action="voice-reset">Повторить</button></div><small>${voice==='recording'?'Запись… 00:05 (демо)':voice==='preview'||voice==='playing'?'Запись готова · 00:12 · демонстрация':'Нажмите «Записать», затем «Стоп»'}</small></div>`;
 if(b.type==='loading'||b.type==='success')return `<div class="placeholder" style="height:${b.height||140}px">${b.type==='loading'?'<span class="spinner" aria-hidden="true"></span>':'<span style="font-size:36px">✓</span>'}<strong role="status">${esc(b.text)}</strong></div>`;
 if(b.type==='heading')return `<h3 class="heading">${esc(b.text)}</h3>`;
 if(b.type==='badge')return `<span class="badge">${esc(b.text)}</span>`;
 let text=b.text;if(text.startsWith('История:')&&values.resolution)text+='\nВаш ответ: '+values.resolution;
 if(b.key==='confirm-count'&&confirmed)text=text.replace('Подтверждения: 3','Подтверждения: 4 · ваш голос учтён');
 if(b.key==='filter-summary')text=`${values.mapCategory} · радиус ${values.radius}`;
 return `<${b.type==='note'?'div':'p'} class="${b.type==='note'?'note':'block-text'} ${b.small?'small':''}">${esc(text)}</${b.type==='note'?'div':'p'}>`;
}
function dialog(m){return `<div class="dialog" role="dialog" aria-modal="true" aria-label="${esc(m.title)}"><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p>${(m.blocks||[]).map(x=>block(x)).join('')}${m.buttons.map(x=>block(x)).join('')}</div>`;}
function phone(s,live=false){return `<div class="phone ${live?'live':''}" ${live?'id="live-phone"':''}><div class="status"><span>09:41</span><span>QalaPulse · wireframe</span></div><header>${s.back?`<button class="back" data-action="go:${s.back}" aria-label="Назад">‹</button>`:''}<div><h2>${esc(s.title)}</h2><p class="subtitle">${esc(s.subtitle)}</p></div></header><div class="phone-body">${s.blocks.map(x=>block(x,!live)).join('')}<div class="error" id="form-error" role="alert" hidden></div></div>${s.nav?`<div class="bottom-nav">${[['Главная','01'],['Карта','02'],['+','06'],['События','14'],['Профиль','15']].map(([t,id])=>`<button data-action="go:${id}" class="${s.id===id?'selected':''}" aria-label="${t==='+'?'Создать':t}">${t}</button>`).join('')}</div>`:''}${live&&modal?`<div class="overlay">${dialog(SPEC.modals.find(x=>x.id===modal))}</div>`:''}${live?'<div class="toast" role="status" aria-live="polite"></div>':''}</div>`;}
function setTab(next){tab=next;clearTimeout(timer);modal=null;render();window.scrollTo(0,0);}
function render(){
 document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));
 const out=$('main');
 if(tab==='prototype'){out.innerHTML=`<div class="live-layout">${phone(SPEC.screens.find(s=>s.id===current),true)}<aside class="help"><p class="eyebrow">ИНТЕРАКТИВНЫЙ ПРОТОТИП · ${current} / 15</p><h2>Проверьте сценарий</h2><ol><li>Нажмите «Сообщить о проблеме».</li><li>Добавьте условное фото и подтвердите точку.</li><li>Введите текст или попробуйте состояния голосовой записи.</li><li>Проверьте AI-результат и поставьте отметку.</li><li>Подтвердите дубликат или опубликуйте новое обращение.</li></ol><p>На экране дубликатов доступна демонстрация ошибки сети. Поля черновика сохраняются при перезагрузке.</p><p><strong>Это макет.</strong> Камера, GPS, аудио, AI и отправка на сервер имитируются. Не вводите реальные пароли.</p><button class="action" data-action="reset-demo">Начать демонстрацию заново</button><p><a href="figma-plugin/manifest.json" download>Manifest плагина Figma</a> · <a href="README.md">Инструкция</a></p></aside></div>`;return;}
 if(tab==='screens'){out.innerHTML=`<p class="intro">15 экранов и состояний одного проекта. Нажмите «Открыть в прототипе», чтобы проверить переходы. Серые поля фотографий и схематичная карта намеренно обозначают контент в low-fidelity wireframes.</p><div class="gallery">${SPEC.screens.map(s=>`<section class="sheet"><h2><span class="screen-index">${s.id}</span>${esc(s.title)} — ${esc(s.subtitle)}</h2>${phone(s)}<button class="action gallery-open" data-action="open:${s.id}">Открыть в прототипе</button></section>`).join('')}</div><h2>5 связанных модальных окон</h2><div class="gallery">${SPEC.modals.map(m=>`<section class="sheet modal-sheet"><h2>${m.id} · ${esc(m.title)}</h2><div class="phone">${dialog(m)}</div></section>`).join('')}</div>`;return;}
 if(tab==='flow'){out.innerHTML=`<p class="intro">Сплошные блоки — экраны, пунктирные — модальные окна. Стрелки показывают направление действий. У каждого модального окна есть путь отмены, возвращающий к исходному экрану.</p>${SPEC.flows.map(f=>`<section class="flow"><h2>${esc(f.title)}</h2><div class="flow-steps">${f.steps.map((x,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="flow-node ${x.startsWith('M')?'modal-node':''}">${esc(x)}</div>`).join('')}</div></section>`).join('')}<section class="flow"><h2>Развилки</h2><p>11 → результат не проверен → кнопка заблокирована; результат проверен → 12.</p><p>12 → найден дубликат → подтвердить существующее → 03; создать отдельное → M3 → 13.</p><p>M3 → отмена → 12; вернуться к проверке → 11. M5 → повторить → 13 или продолжить позже → 15.</p><p>M4 → решена / частично / всё ещё есть → 03 + запись ответа. M1 и M2 → отмена → исходный экран.</p></section>`;return;}
 if(tab==='states'){const examples=[['Default','Продолжить','','Можно перейти к следующему шагу.'],['Hover','Продолжить','hover','Наведение мышью для проверки в браузере.'],['Pressed / Active','Продолжить','pressed','Кнопка удерживается пальцем или мышью.'],['Disabled','Продолжить','disabled','Фото не выбрано или результат AI не проверен.'],['Loading','Подождите…','loading','Повторное нажатие блокируется до завершения.']];out.innerHTML=`<p class="intro">Состояния показывают доступность действия. На телефоне основное состояние взаимодействия — нажатие; hover относится к просмотру прототипа мышью.</p><div class="states">${examples.map(([title,label,state,note])=>`<section class="state"><h2>${title}</h2><button class="btn ${state}" style="${state==='hover'?'background:#505050':state==='pressed'?'background:#000;transform:translateY(1px)':''}" ${['disabled','loading'].includes(state)?'disabled':''}>${label}</button><p>${note}</p></section>`).join('')}<section class="state"><h2>Ошибка формы</h2><label class="field"><span>Электронная почта</span><input value="resident" aria-invalid="true"></label><p class="error">Введите корректный email. Остальные поля сохранены.</p></section><section class="state"><h2>Успех</h2><p class="note">Подтверждение принято. Ваш голос учтён один раз.</p></section><section class="state"><h2>Offline</h2><p class="note">Нет соединения. Черновик сохранён — повторите отправку.</p></section></div>`;return;}
 out.innerHTML=`<article class="report"><p class="eyebrow">LABORATORY WORK №4</p><h1>QalaPulse: Wireframes Improvement and Interactive Elements</h1><h2>Цель</h2><p>Расширить существующий мобильный проект QalaPulse: показать полный путь жителя от обнаружения городской проблемы до публикации, подтверждения и проверки решения.</p><h2>Что улучшено</h2><p>За основу взяты существующие разделы приложения: главная, карта, создание, события и профиль. Добавлены явно показанные состояния пустого и заполненного фото, анализа AI, обязательной проверки человеком, выбора дубликата и успеха. Модальные окна соединены с вызывающими кнопками и путями отмены. Сбой сети демонстрирует сохранение черновика.</p><table><thead><tr><th>Требование</th><th>Результат</th></tr></thead><tbody><tr><td>10–15 экранов / состояний</td><td>15 основных экранов + состояния компонентов</td></tr><tr><td>2–5 модальных окон</td><td>5: фото, фильтры, публикация, решение, сеть</td></tr><tr><td>Updated User Flow</td><td>5 сценариев со стрелками и развилками</td></tr><tr><td>Интерактивность</td><td>Навигация, формы, фильтры, переключатели, проверка AI, отмена и повтор</td></tr><tr><td>Figma</td><td>Плагин создаёт редактируемые макеты, компоненты и native prototype connections. Требуется локальный импорт и запуск.</td></tr></tbody></table><h2>Ограничения</h2><p>HTML используется для проверки сценариев. Это не замена обязательной сдаче файла Figma. Автоматическое заполнение Figma остановлено лимитом MCP Starter. В Figma ввод данных представлен предзаполненными полями; полноценная проверка ввода доступна в HTML. Поиск и меню фильтров — предложения для развития wireframes, а не утверждение о готовности всех функций приложения.</p><h2>Вывод</h2><p>Макеты описывают действия, обратную связь и альтернативные пути. Пользователь сохраняет контроль над AI-результатом и дубликатами. Структура готова к следующему этапу визуального UI-дизайна.</p></article>`;
}
function go(id){clearTimeout(timer);modal=null;current=id;tab='prototype';render();window.scrollTo(0,0);applyMapFilter();if(id==='10')timer=setTimeout(()=>{if(current==='10'&&!modal)go('11');},1500);}
function syncReview(){if(current!=='11')return;const next=$('[data-action="review-next"]'),check=$('[data-key="reviewed"]');if(next)next.disabled=!values.reviewed;if(check)check.checked=!!values.reviewed;}
function applyMapFilter(){if(current!=='02'||tab!=='prototype')return;const card=$('#live-phone .card');if(card)card.hidden=values.mapCategory==='Мусор'||!card.dataset.searchable.includes((values.search||'').toLowerCase());if(card?.hidden)toast('Подходящих обращений нет. Измените поиск или фильтр.');}
function toast(text){const t=$('.toast');if(t){t.textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(t.isConnected)t.textContent='';},4500);}}
function formError(message){const el=$('#live-phone #form-error');el.hidden=false;el.textContent=message;el.scrollIntoView({block:'nearest'});}
document.addEventListener('input',e=>{const key=e.target.dataset.key;if(!key)return;values[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(['title','description','category','severity'].includes(key))values.reviewed=false;persist();syncReview();if(key==='search'){const cards=document.querySelectorAll('#live-phone [data-searchable]');let shown=0;cards.forEach(c=>{const match=values.mapCategory!=='Мусор'&&c.dataset.searchable.includes(values.search.toLowerCase());c.hidden=!match;if(match)shown++;});if(!shown)toast('По запросу ничего не найдено. Измените поиск.');}});
document.addEventListener('change',e=>{const key=e.target.dataset.key;if(!key)return;values[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(['category','severity'].includes(key))values.reviewed=false;persist();syncReview();});
document.addEventListener('click',e=>{const t=e.target.closest('[data-tab],[data-action]');if(!t||t.disabled)return;if(t.dataset.tab){setTab(t.dataset.tab);return;}const a=t.dataset.action;if(!a)return;
 if(a.startsWith('open:')||a.startsWith('go:')){go(a.split(':')[1]);return;}
 if(a.startsWith('modal:')){clearTimeout(timer);modal=a.slice(6);render();$('.dialog button')?.focus();return;}
 if(a==='close'){modal=null;render();return;}
 if(a==='photo-camera'||a==='photo-gallery'){values.photo=true;persist();go('07');toast('Условное фото добавлено');return;}
 if(a==='login'||a==='register'){const email=$('[data-key="email"]').value;const pass=$('[data-key="password"]').value;const name=$('[data-key="name"]')?.value;if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)||pass.length<(a==='register'?10:1)||(a==='register'&&name.trim().length<2)){formError('Проверьте email, пароль и обязательные поля. Введённый текст сохранён.');return;}go('06');toast('Демонстрационный вход выполнен');return;}
 if(a==='gps'||a==='pick-location'){values.coordinates=a==='gps'?'43.238900, 76.889700':'43.239150, 76.890050';persist();render();toast('Условная точка выбрана. Проверьте адрес.');return;}
 if(a==='gps-map'){toast('Карта перемещена к условной позиции в Алматы');return;}
 if(a==='apply-filters'||a==='reset-filters'){if(a==='reset-filters'){values.mapCategory='Все категории';values.radius='1 км';}persist();modal=null;render();toast('Фильтры применены');applyMapFilter();return;}
 if(a==='review-next'){if(!values.reviewed)return;const severity=Number(values.severity??9);if(severity<1||severity>10||!Number.isFinite(severity)){formError('Укажите опасность от 1 до 10.');return;}go('12');return;}
 if(a==='confirm-existing'||a==='confirm-duplicate'){const already=confirmed;confirmed=true;if(a==='confirm-duplicate')go('03');else render();toast(already?'Вы уже подтвердили эту проблему.':'Подтверждение принято. Ваш голос учтён.');return;}
 if(a==='publish'||a==='retry'){if(!values.reviewed){go('11');toast('Сначала проверьте результат.');return;}values.published=true;persist();go('13');return;}
 if(['resolved','partial','unresolved'].includes(a)){values.resolution={resolved:'Решена',partial:'Решена частично',unresolved:'Проблема всё ещё есть'}[a];persist();go('03');toast({resolved:'Ваш ответ «Решена» добавлен в историю.',partial:'Ваш ответ «Решена частично» добавлен в историю.',unresolved:'Ваш ответ «Проблема всё ещё есть» добавлен в историю.'}[a]);return;}
 if(a==='voice-record'){voice=voice==='recording'?'preview':'recording';if(voice==='preview'){values.description='Открытый люк у остановки на улице Абая.';values.reviewed=false;persist();}render();return;}
 if(a==='voice-play'){voice=voice==='playing'?'preview':'playing';render();toast('Предпрослушивание: демонстрация состояния, без записи звука.');return;}
 if(a==='voice-reset'){voice='idle';render();return;}
 if(a==='comment'){if(!(values.comment||'').trim()){formError('Введите комментарий.');return;}const note=document.createElement('div');note.className='note';note.textContent='Ваш комментарий: '+values.comment;$('#live-phone .phone-body').appendChild(note);values.comment='';persist();toast('Комментарий добавлен в демонстрационном сценарии.');return;}
 if(a==='refresh-events'){toast('События обновлены');return;}
 if(a==='my-incidents'){go('01');toast('Учебный список моих обращений');return;}
 if(a==='logout'){go('04');toast('Вы вышли из демонстрационного аккаунта');return;}
 if(a==='reset-demo'){Object.keys(values).forEach(k=>delete values[k]);Object.assign(values,defaults);confirmed=false;voice='idle';persist();go('01');}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render();}});
render();
